
const HTML = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#f5f2ea\">\n  <meta name=\"description\" content=\"Learn useful English by listening, repeating, recalling, and using it with a Tavus video coach.\">\n  <meta property=\"og:title\" content=\"Fluent Me — learn it, then use it\">\n  <meta property=\"og:description\" content=\"Learn three useful English phrases with a face-to-face AI coach.\">\n  <meta property=\"og:image\" content=\"/static/og-language-lesson.png\">\n  <meta name=\"twitter:card\" content=\"summary_large_image\">\n  <title>Fluent Me — learn it, then use it</title>\n  <link rel=\"stylesheet\" href=\"/static/live.css\">\n  <script crossorigin src=\"https://unpkg.com/@daily-co/daily-js@0.91.0\"></script>\n</head>\n<body data-view=\"welcome\" data-lesson-step=\"listen\" data-coach-mode=\"checking\">\n  <div class=\"app-shell\">\n    <header class=\"topbar\">\n      <a class=\"brand\" href=\"/\" aria-label=\"Fluent Me 首页\">\n        <span class=\"brand-mark\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i><i></i></span>\n        <span>Fluent Me</span>\n      </a>\n      <div class=\"topbar-center\" id=\"lesson-progress\" hidden>\n        <span id=\"lesson-topic\">Tavus interview English</span>\n        <b id=\"sentence-count\">第 1 / 3 句</b>\n      </div>\n      <button class=\"text-button\" id=\"exit-button\" type=\"button\" hidden>退出练习</button>\n    </header>\n\n    <main>\n      <section class=\"welcome\" id=\"welcome\" aria-labelledby=\"welcome-title\">\n        <div class=\"welcome-copy\">\n          <p class=\"eyebrow\">5-minute English lesson</p>\n          <h1 id=\"welcome-title\">三句话，<br>真正说出口。</h1>\n          <p class=\"welcome-lede\">先听教练示范，再跟读、纠正、脱稿，最后把它用进一段真实对话。</p>\n\n          <div class=\"lesson-preview\" aria-label=\"今天的课程步骤\">\n            <div><span>01</span><b>听一句</b><small>看着教练，听自然表达</small></div>\n            <div><span>02</span><b>说出来</b><small>跟读，只改最关键的一处</small></div>\n            <div><span>03</span><b>用进去</b><small>脱稿后放进真实回答</small></div>\n          </div>\n\n          <button class=\"primary-button welcome-start\" id=\"start-lesson\" type=\"button\">\n            <span>连接 Tavus 教练</span><i aria-hidden=\"true\">→</i>\n          </button>\n          <p class=\"welcome-note\">今天主题：如何解释 Tavus 不只是一个数字人脸</p>\n        </div>\n\n        <aside class=\"welcome-coach\" aria-label=\"Tavus 视频教练预览\">\n          <div class=\"coach-preview-frame\">\n            <div class=\"tavus-waiting-canvas\" aria-label=\"等待连接真实 Tavus 视频\">\n              <span>TAVUS</span><i></i><b>LIVE VIDEO</b>\n            </div>\n            <div class=\"coach-preview-badge\"><i></i><span>等待连接真实 Tavus 视频</span></div>\n            <div class=\"coach-preview-copy\">\n              <p>YOUR VIDEO COACH</p>\n              <h2>点击开始，直接连接 Tavus。</h2>\n              <span>这里不放静态人脸；远端视频轨道出现后才显示教练。</span>\n            </div>\n          </div>\n          <div class=\"coach-readiness\" id=\"welcome-readiness\" aria-live=\"polite\">\n            <span class=\"status-dot\"></span>\n            <div><b id=\"welcome-status\">正在检查 Tavus 连接…</b><small id=\"welcome-status-detail\">不会在未连接时假装在线</small></div>\n          </div>\n        </aside>\n      </section>\n\n      <section class=\"lesson\" id=\"lesson\" hidden aria-label=\"英语练习课程\">\n        <nav class=\"stepper\" aria-label=\"课程步骤\">\n          <ol>\n            <li data-step=\"listen\"><span>1</span><div><b>先听</b><small>Listen</small></div></li>\n            <li data-step=\"repeat\"><span>2</span><div><b>跟读</b><small>Repeat</small></div></li>\n            <li data-step=\"fix\"><span>3</span><div><b>改一处</b><small>Fix</small></div></li>\n            <li data-step=\"recall\"><span>4</span><div><b>脱稿</b><small>Recall</small></div></li>\n            <li data-step=\"use\"><span>5</span><div><b>对话</b><small>Use</small></div></li>\n          </ol>\n        </nav>\n\n        <div class=\"lesson-grid\">\n          <section class=\"coach-stage\" aria-label=\"视频教练\">\n            <div class=\"coach-still tavus-waiting-canvas\" id=\"coach-still\" aria-label=\"等待连接真实 Tavus 视频\">\n              <span>TAVUS</span><i></i><b>CONNECTING</b>\n            </div>\n            <div class=\"daily-stage\" id=\"daily-stage\" hidden></div>\n\n            <div class=\"coach-state\" id=\"coach-state\">\n              <span class=\"coach-state-dot\"></span>\n              <b id=\"coach-state-label\">正在连接视频教练</b>\n            </div>\n            <div class=\"preview-ribbon\" id=\"preview-ribbon\">等待真实 TAVUS 视频</div>\n            <div class=\"coach-caption\" id=\"coach-caption\" aria-live=\"polite\">\n              <span id=\"caption-speaker\">教练</span>\n              <p id=\"caption-text\">连接后，教练会在这里示范并与你对话。</p>\n            </div>\n\n            <div class=\"connection-card\" id=\"connection-card\" hidden>\n              <p id=\"connection-title\">视频教练暂未连接</p>\n              <span id=\"connection-copy\">这不是预览模式。请重新连接真实 Tavus 视频教练。</span>\n              <div>\n                <button class=\"small-button strong\" id=\"retry-tavus\" type=\"button\">重新连接 Tavus</button>\n              </div>\n            </div>\n          </section>\n\n          <section class=\"task-panel\" aria-labelledby=\"task-title\">\n            <div class=\"task-heading\">\n              <p class=\"task-index\" id=\"task-index\">第 1 / 5 步 · LISTEN</p>\n              <h2 id=\"task-title\">先听教练说，不用开口。</h2>\n              <p id=\"task-instruction\">注意句子里两个自然的意群。</p>\n            </div>\n\n            <div class=\"phrase-card\" id=\"phrase-card\">\n              <p class=\"target-phrase\" id=\"target-phrase\">Tavus is more than a digital face.</p>\n              <p class=\"translation\" id=\"translation\">Tavus 不只是一个数字人脸。</p>\n              <div class=\"chunks\" id=\"chunks\" aria-label=\"句子意群\"></div>\n            </div>\n\n            <div class=\"capture-result\" id=\"capture-result\" hidden aria-live=\"polite\">\n              <span id=\"capture-label\">我听到你说</span>\n              <p id=\"capture-text\"></p>\n              <div class=\"capture-actions\">\n                <button class=\"inline-button\" id=\"play-recording\" type=\"button\" hidden>▶ 听我的录音</button>\n                <button class=\"inline-button\" id=\"edit-transcript\" type=\"button\">文字不对？修改</button>\n              </div>\n            </div>\n\n            <div class=\"text-entry\" id=\"text-entry\" hidden>\n              <label for=\"typed-answer\">输入你刚才说的英文</label>\n              <textarea id=\"typed-answer\" rows=\"3\" maxlength=\"500\" placeholder=\"Type what you said…\"></textarea>\n              <button class=\"small-button strong\" id=\"submit-text\" type=\"button\">使用这句话</button>\n            </div>\n\n            <div class=\"task-note\" id=\"task-note\" hidden>\n              <span id=\"task-note-label\">只改这一处</span>\n              <b id=\"task-note-title\"></b>\n              <p id=\"task-note-copy\"></p>\n            </div>\n\n            <div class=\"task-actions\">\n              <button class=\"secondary-button\" id=\"secondary-action\" type=\"button\">再听一遍</button>\n              <button class=\"primary-button\" id=\"primary-action\" type=\"button\">\n                <span>轮到我</span><i aria-hidden=\"true\">→</i>\n              </button>\n            </div>\n            <div class=\"action-meta\">\n              <p class=\"action-help\" id=\"action-help\">点击“轮到我”后，再开始说。</p>\n              <button class=\"type-instead\" id=\"type-instead\" type=\"button\" hidden>没有麦克风？输入英文</button>\n            </div>\n          </section>\n        </div>\n      </section>\n\n      <section class=\"complete\" id=\"complete\" hidden aria-labelledby=\"complete-title\">\n        <div class=\"complete-copy\">\n          <p class=\"eyebrow\">Lesson complete</p>\n          <h1 id=\"complete-title\">这三句话，<br>你已经用出来了。</h1>\n          <p>明天不要先看原句。换一个问题，把它们从记忆里叫回来。</p>\n        </div>\n        <div class=\"learned-list\" id=\"learned-list\"></div>\n        <div class=\"complete-actions\">\n          <button class=\"primary-button\" id=\"practice-again\" type=\"button\"><span>再练一遍</span><i>↻</i></button>\n          <button class=\"secondary-button\" id=\"back-home\" type=\"button\">回到首页</button>\n        </div>\n      </section>\n    </main>\n  </div>\n\n  <div class=\"recording-toast\" id=\"recording-toast\" hidden>\n    <span class=\"recording-pulse\"></span>\n    <div><b>正在听你说</b><small id=\"recording-hint\">说完后点“完成”</small></div>\n    <button id=\"stop-recording\" type=\"button\">完成</button>\n  </div>\n\n  <script src=\"/static/live.js\" defer></script>\n</body>\n</html>\n";
const CSS = ":root {\n  color-scheme: light;\n  --paper: #f5f2ea;\n  --paper-2: #ece8dd;\n  --ink: #17211c;\n  --muted: #687069;\n  --line: rgba(23, 33, 28, .16);\n  --forest: #173f32;\n  --forest-2: #0f3026;\n  --mint: #b9f4d7;\n  --coral: #f26c4f;\n  --cream: #fffdf7;\n  --shadow: 0 24px 70px rgba(24, 33, 28, .14);\n  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n* { box-sizing: border-box; }\nhtml { min-width: 320px; background: var(--paper); }\nbody { margin: 0; min-height: 100dvh; background: var(--paper); color: var(--ink); }\nbutton, textarea { font: inherit; }\nbutton { -webkit-tap-highlight-color: transparent; }\n[hidden] { display: none !important; }\n\n.app-shell { width: min(1440px, 100%); min-height: 100dvh; margin: 0 auto; padding: 0 clamp(18px, 3vw, 46px) 38px; }\n.topbar { height: 78px; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; border-bottom: 1px solid var(--line); }\n.brand { display: inline-flex; align-items: center; gap: 12px; width: fit-content; color: var(--ink); text-decoration: none; font-size: 16px; font-weight: 760; letter-spacing: -.02em; }\n.brand-mark { width: 31px; height: 22px; display: flex; align-items: center; justify-content: center; gap: 2px; }\n.brand-mark i { display: block; width: 3px; border-radius: 99px; background: var(--forest); }\n.brand-mark i:nth-child(1), .brand-mark i:nth-child(5) { height: 8px; }\n.brand-mark i:nth-child(2), .brand-mark i:nth-child(4) { height: 15px; background: var(--coral); }\n.brand-mark i:nth-child(3) { height: 22px; }\n.topbar-center { display: flex; align-items: center; gap: 15px; font-size: 12px; }\n.topbar-center span { color: var(--muted); }\n.topbar-center b { padding-left: 15px; border-left: 1px solid var(--line); font-weight: 650; }\n.text-button { justify-self: end; border: 0; background: transparent; padding: 10px 0 10px 15px; color: var(--muted); cursor: pointer; }\n.text-button:hover { color: var(--coral); }\n\n.eyebrow { margin: 0 0 18px; color: var(--forest); font-size: 11px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }\n.welcome { min-height: calc(100dvh - 116px); display: grid; grid-template-columns: minmax(380px, .82fr) minmax(520px, 1.18fr); align-items: center; gap: clamp(42px, 6vw, 90px); padding: 58px 0 40px; }\n.welcome-copy { max-width: 610px; }\n.welcome h1, .complete h1 { margin: 0; font-family: Georgia, \"Times New Roman\", serif; font-size: clamp(58px, 6.4vw, 98px); line-height: .94; letter-spacing: -.06em; font-weight: 500; }\n.welcome-lede { max-width: 560px; margin: 28px 0 0; color: var(--muted); font-size: 17px; line-height: 1.7; }\n.lesson-preview { display: grid; grid-template-columns: repeat(3, 1fr); gap: 13px; margin-top: 38px; }\n.lesson-preview > div { min-width: 0; padding: 17px 16px; border: 1px solid var(--line); border-radius: 14px; background: rgba(255,253,247,.55); }\n.lesson-preview span, .lesson-preview b, .lesson-preview small { display: block; }\n.lesson-preview span { color: var(--coral); font-size: 9px; font-weight: 800; letter-spacing: .1em; }\n.lesson-preview b { margin-top: 11px; font-size: 13px; }\n.lesson-preview small { margin-top: 5px; color: var(--muted); font-size: 10px; line-height: 1.45; }\n.welcome-start { width: 245px; margin-top: 34px; }\n.welcome-note { margin: 14px 0 0; color: var(--muted); font-size: 11px; }\n\n.welcome-coach { width: 100%; max-width: 720px; justify-self: end; }\n.coach-preview-frame { position: relative; min-height: clamp(470px, 63vh, 690px); overflow: hidden; border-radius: 28px 28px 9px 9px; background: #171714; box-shadow: var(--shadow); }\n.tavus-waiting-canvas { position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 13px; overflow: hidden; background: radial-gradient(circle at 50% 42%, rgba(185,244,215,.13), transparent 25%), linear-gradient(145deg, #0c2119, #173f32 55%, #0b241b); color: rgba(255,255,255,.84); }\n.tavus-waiting-canvas::before, .tavus-waiting-canvas::after { content: \"\"; position: absolute; width: 62%; aspect-ratio: 1; border: 1px solid rgba(185,244,215,.12); border-radius: 50%; }\n.tavus-waiting-canvas::after { width: 38%; }\n.tavus-waiting-canvas span, .tavus-waiting-canvas b, .tavus-waiting-canvas i { position: relative; z-index: 1; }\n.tavus-waiting-canvas span { font-family: Georgia, \"Times New Roman\", serif; font-size: clamp(56px, 7vw, 96px); letter-spacing: -.05em; }\n.tavus-waiting-canvas i { width: 45px; height: 2px; background: var(--coral); }\n.tavus-waiting-canvas b { color: var(--mint); font-size: 9px; letter-spacing: .22em; }\n.coach-preview-badge { position: absolute; top: 22px; left: 22px; display: flex; align-items: center; gap: 9px; padding: 9px 12px; border: 1px solid rgba(255,255,255,.3); border-radius: 99px; background: rgba(10,18,14,.58); color: white; backdrop-filter: blur(16px); font-size: 10px; }\n.coach-preview-badge i { width: 7px; height: 7px; border-radius: 50%; background: #ffbb53; }\n.coach-preview-copy { position: absolute; left: 31px; right: 31px; bottom: 30px; color: white; }\n.coach-preview-copy p { margin: 0 0 8px; color: var(--mint); font-size: 9px; font-weight: 800; letter-spacing: .14em; }\n.coach-preview-copy h2 { margin: 0; font-family: Georgia, \"Times New Roman\", serif; font-size: clamp(31px, 3.3vw, 49px); font-weight: 500; letter-spacing: -.04em; }\n.coach-preview-copy span { display: block; max-width: 470px; margin-top: 11px; color: rgba(255,255,255,.76); font-size: 12px; line-height: 1.5; }\n.coach-readiness { display: flex; align-items: center; gap: 13px; min-height: 69px; padding: 0 22px; border-radius: 0 0 18px 18px; background: var(--forest); color: white; }\n.status-dot { width: 9px; height: 9px; flex: 0 0 auto; border-radius: 50%; background: #f2b454; box-shadow: 0 0 0 6px rgba(242,180,84,.12); }\n.coach-readiness b, .coach-readiness small { display: block; }\n.coach-readiness b { font-size: 12px; }\n.coach-readiness small { margin-top: 3px; color: rgba(255,255,255,.64); font-size: 10px; }\nbody[data-coach-mode=\"tavus-ready\"] .status-dot { background: #60e0ae; box-shadow: 0 0 0 6px rgba(96,224,174,.12); }\nbody[data-coach-mode=\"audio\"] .status-dot, body[data-coach-mode=\"unavailable\"] .status-dot { background: #f2b454; }\n\n.primary-button, .secondary-button, .small-button, .inline-button { border: 0; cursor: pointer; }\n.primary-button { min-height: 55px; display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 0 20px; border-radius: 12px; background: var(--coral); color: white; box-shadow: 0 12px 28px rgba(242,108,79,.18); transition: transform .16s ease, background .16s ease; }\n.primary-button:hover:not(:disabled) { transform: translateY(-1px); background: #df5d42; }\n.primary-button:disabled { opacity: .45; cursor: not-allowed; box-shadow: none; }\n.primary-button span { font-size: 13px; font-weight: 740; }\n.primary-button i { font-size: 20px; font-style: normal; }\n.secondary-button { min-height: 55px; padding: 0 18px; border: 1px solid var(--line); border-radius: 12px; background: transparent; color: var(--ink); font-size: 12px; }\n.secondary-button:hover { background: rgba(255,255,255,.5); }\n\n.lesson { padding: 25px 0 0; }\n.stepper { width: min(860px, 100%); margin: 0 auto 22px; }\n.stepper ol { list-style: none; display: grid; grid-template-columns: repeat(5, 1fr); margin: 0; padding: 0; }\n.stepper li { position: relative; display: flex; align-items: center; gap: 9px; color: #9a9e98; }\n.stepper li:not(:last-child)::after { content: \"\"; position: absolute; z-index: -1; left: 31px; right: 6px; top: 15px; height: 1px; background: var(--line); }\n.stepper li > span { width: 30px; height: 30px; flex: 0 0 auto; display: grid; place-items: center; border: 1px solid var(--line); border-radius: 50%; background: var(--paper); font-size: 10px; font-weight: 700; }\n.stepper b, .stepper small { display: block; }\n.stepper b { font-size: 10px; }\n.stepper small { margin-top: 2px; font-size: 8px; text-transform: uppercase; letter-spacing: .08em; }\n.stepper li.active { color: var(--forest); }\n.stepper li.active > span { border-color: var(--forest); background: var(--forest); color: white; }\n.stepper li.done { color: var(--forest); }\n.stepper li.done > span { border-color: rgba(23,63,50,.24); background: var(--mint); color: var(--forest); }\n\n.lesson-grid { min-height: min(735px, calc(100dvh - 162px)); display: grid; grid-template-columns: minmax(520px, 1.35fr) minmax(380px, .85fr); border: 1px solid var(--line); border-radius: 24px; overflow: hidden; background: var(--cream); box-shadow: var(--shadow); }\n.coach-stage { position: relative; min-height: 600px; overflow: hidden; background: #171714; }\n.coach-still { position: absolute; inset: 0; }\n.daily-stage { position: absolute; inset: 0; z-index: 2; background: #0c0f0d; }\n.daily-stage.pending { opacity: 0; pointer-events: none; }\n.daily-stage iframe { display: block; width: 100% !important; height: 100% !important; border: 0 !important; }\n.coach-state, .preview-ribbon, .coach-caption, .connection-card { z-index: 5; }\n.coach-state { position: absolute; top: 20px; left: 20px; display: flex; align-items: center; gap: 9px; padding: 9px 12px; border: 1px solid rgba(255,255,255,.24); border-radius: 99px; background: rgba(10,18,14,.65); color: white; backdrop-filter: blur(14px); font-size: 10px; }\n.coach-state-dot { width: 7px; height: 7px; border-radius: 50%; background: #f2b454; }\nbody[data-coach-mode=\"tavus-live\"] .coach-state-dot { background: #60e0ae; box-shadow: 0 0 0 5px rgba(96,224,174,.13); }\nbody[data-coach-mode=\"speaking\"] .coach-state-dot { background: var(--coral); box-shadow: 0 0 0 5px rgba(242,108,79,.13); }\nbody[data-coach-mode=\"listening\"] .coach-state-dot { background: #8fb9ff; box-shadow: 0 0 0 5px rgba(143,185,255,.13); }\n.preview-ribbon { position: absolute; top: 20px; right: 20px; padding: 9px 11px; border-radius: 99px; background: rgba(10,18,14,.65); color: rgba(255,255,255,.8); backdrop-filter: blur(14px); font-size: 8px; letter-spacing: .1em; }\n.coach-caption { position: absolute; left: 20px; right: 20px; bottom: 20px; padding: 15px 17px; border: 1px solid rgba(255,255,255,.2); border-radius: 14px; background: rgba(10,18,14,.75); color: white; backdrop-filter: blur(15px); }\n.coach-caption span { display: block; margin-bottom: 5px; color: var(--mint); font-size: 8px; font-weight: 800; text-transform: uppercase; letter-spacing: .11em; }\n.coach-caption p { margin: 0; font-size: 13px; line-height: 1.5; }\n.connection-card { position: absolute; left: 50%; top: 50%; width: min(390px, calc(100% - 48px)); transform: translate(-50%, -50%); padding: 22px; border: 1px solid rgba(255,255,255,.25); border-radius: 18px; background: rgba(13,24,19,.92); color: white; backdrop-filter: blur(20px); box-shadow: 0 20px 60px rgba(0,0,0,.35); }\n.connection-card p { margin: 0; font-size: 17px; font-weight: 720; }\n.connection-card > span { display: block; margin-top: 9px; color: rgba(255,255,255,.68); font-size: 11px; line-height: 1.55; }\n.connection-card > div { display: flex; gap: 8px; margin-top: 17px; }\n.small-button { padding: 10px 12px; border: 1px solid rgba(255,255,255,.24); border-radius: 9px; background: transparent; color: inherit; font-size: 10px; }\n.small-button.strong { border-color: transparent; background: var(--coral); color: white; }\n\n.task-panel { position: relative; display: flex; flex-direction: column; padding: clamp(32px, 4vw, 60px); background: var(--cream); }\n.task-index { margin: 0 0 14px; color: var(--coral); font-size: 9px; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; }\n.task-heading h2 { max-width: 620px; margin: 0; font-family: Georgia, \"Times New Roman\", serif; font-size: clamp(31px, 3vw, 47px); line-height: 1.07; letter-spacing: -.04em; font-weight: 500; }\n.task-heading > p:last-child { margin: 14px 0 0; color: var(--muted); font-size: 13px; line-height: 1.55; }\n.phrase-card { margin-top: 38px; padding: 29px; border: 1px solid var(--line); border-radius: 18px; background: var(--paper); }\n.target-phrase { margin: 0; font-family: Georgia, \"Times New Roman\", serif; font-size: clamp(27px, 2.7vw, 42px); line-height: 1.18; letter-spacing: -.035em; }\n.translation { margin: 16px 0 0; color: var(--muted); font-size: 13px; }\n.chunks { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 22px; }\n.chunks span { padding: 8px 11px; border-radius: 99px; background: white; color: var(--forest); font-size: 10px; font-weight: 650; }\nbody[data-lesson-step=\"recall\"] .target-phrase { filter: blur(9px); user-select: none; opacity: .2; }\nbody[data-lesson-step=\"recall\"] .chunks { display: none; }\nbody[data-lesson-step=\"use\"] .translation { display: none; }\n\n.capture-result { margin-top: 16px; padding: 17px 19px; border-left: 3px solid var(--forest); border-radius: 4px 12px 12px 4px; background: rgba(185,244,215,.24); }\n.capture-result > span { color: var(--muted); font-size: 9px; text-transform: uppercase; letter-spacing: .09em; }\n.capture-result > p { margin: 8px 0 0; font-size: 14px; line-height: 1.5; }\n.capture-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 11px; }\n.inline-button { padding: 0; background: transparent; color: var(--forest); font-size: 10px; font-weight: 650; }\n.text-entry { margin-top: 16px; padding: 16px; border: 1px solid var(--line); border-radius: 12px; background: white; }\n.text-entry label { display: block; margin-bottom: 8px; color: var(--muted); font-size: 10px; }\n.text-entry textarea { width: 100%; resize: vertical; padding: 12px; border: 1px solid var(--line); border-radius: 9px; color: var(--ink); background: var(--cream); line-height: 1.45; }\n.text-entry .small-button { width: 100%; min-height: 44px; margin-top: 9px; }\n.task-note { margin-top: 17px; padding: 18px 19px; border-radius: 12px; background: var(--forest); color: white; }\n.task-note span { color: var(--mint); font-size: 8px; font-weight: 800; letter-spacing: .11em; text-transform: uppercase; }\n.task-note b { display: block; margin-top: 8px; font-size: 15px; }\n.task-note p { margin: 7px 0 0; color: rgba(255,255,255,.68); font-size: 11px; line-height: 1.5; }\n.task-actions { display: flex; gap: 10px; margin-top: auto; padding-top: 28px; }\n.task-actions .primary-button { min-width: 195px; }\n.action-meta { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-top: 11px; }\n.action-help { margin: 0; color: var(--muted); font-size: 9px; }\n.type-instead { flex: 0 0 auto; min-height: 38px; padding: 0 4px; border: 0; background: transparent; color: var(--forest); font-size: 10px; font-weight: 750; text-decoration: underline; text-decoration-color: rgba(30,72,52,.28); text-underline-offset: 3px; cursor: pointer; }\n.type-instead:hover { text-decoration-color: currentColor; }\n\n.recording-toast { position: fixed; z-index: 100; left: 50%; bottom: max(24px, env(safe-area-inset-bottom)); width: min(430px, calc(100% - 32px)); transform: translateX(-50%); display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 13px; padding: 12px 13px 12px 17px; border-radius: 16px; background: #18241e; color: white; box-shadow: 0 18px 50px rgba(11,20,15,.32); }\n.recording-pulse { width: 11px; height: 11px; border-radius: 50%; background: var(--coral); box-shadow: 0 0 0 0 rgba(242,108,79,.5); animation: pulse 1.3s infinite; }\n.recording-toast b, .recording-toast small { display: block; }\n.recording-toast b { font-size: 11px; }\n.recording-toast small { margin-top: 3px; color: rgba(255,255,255,.62); font-size: 9px; }\n.recording-toast button { border: 0; border-radius: 9px; background: white; padding: 9px 14px; color: var(--ink); font-size: 10px; font-weight: 700; cursor: pointer; }\n@keyframes pulse { 70% { box-shadow: 0 0 0 9px rgba(242,108,79,0); } 100% { box-shadow: 0 0 0 0 rgba(242,108,79,0); } }\n\n.complete { min-height: calc(100dvh - 95px); padding: 70px 0 30px; }\n.complete-copy { max-width: 850px; }\n.complete-copy > p:last-child { max-width: 590px; margin: 25px 0 0; color: var(--muted); font-size: 16px; line-height: 1.65; }\n.learned-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; margin-top: 50px; }\n.learned-item { padding: 22px; border: 1px solid var(--line); border-radius: 15px; background: var(--cream); }\n.learned-item span { color: var(--coral); font-size: 9px; font-weight: 800; letter-spacing: .1em; }\n.learned-item p { margin: 13px 0 0; font-family: Georgia, \"Times New Roman\", serif; font-size: 20px; line-height: 1.35; }\n.learned-item small { display: block; margin-top: 9px; color: var(--muted); font-size: 10px; line-height: 1.45; }\n.complete-actions { display: flex; gap: 10px; margin-top: 25px; }\n.complete-actions .primary-button { width: 220px; }\n\n@media (max-width: 1050px) {\n  .welcome { grid-template-columns: minmax(340px, .9fr) minmax(430px, 1.1fr); gap: 38px; }\n  .lesson-grid { grid-template-columns: minmax(430px, 1.15fr) minmax(360px, .85fr); }\n  .task-panel { padding: 34px; }\n}\n\n@media (max-width: 820px) {\n  .app-shell { padding-inline: 18px; }\n  .topbar { position: sticky; z-index: 30; top: 0; grid-template-columns: auto 1fr auto; background: rgba(245,242,234,.95); backdrop-filter: blur(14px); }\n  .topbar-center { display: flex; justify-content: center; }\n  .topbar-center span { display: none; }\n  .topbar-center b { font-size: 10px; }\n  .welcome { grid-template-columns: 1fr; padding-top: 42px; }\n  .welcome-copy { grid-row: 2; max-width: 680px; }\n  .welcome-coach { grid-row: 1; max-width: none; }\n  .coach-preview-frame { min-height: min(52dvh, 440px); }\n  .lesson { padding-top: 8px; }\n  .stepper { position: sticky; z-index: 29; top: 78px; margin-bottom: 10px; padding: 9px 5px 27px; background: rgba(245,242,234,.96); backdrop-filter: blur(14px); }\n  .lesson-grid { grid-template-columns: 1fr; min-height: auto; overflow: visible; border: 0; background: transparent; box-shadow: none; }\n  .coach-stage { position: sticky; z-index: 18; top: 144px; min-height: 36dvh; border-radius: 18px; box-shadow: var(--shadow); }\n  .task-panel { min-height: 520px; }\n  .stepper li div { display: none; }\n  .stepper li.active div { position: absolute; top: 34px; left: 50%; display: flex; gap: 5px; transform: translateX(-50%); white-space: nowrap; }\n  .stepper li.active small { margin-top: 0; }\n  .stepper li:not(:last-child)::after { right: 12px; }\n}\n\n@media (max-width: 560px) {\n  .app-shell { padding: 0 12px 28px; }\n  .topbar { height: 66px; }\n  .welcome { min-height: auto; padding-top: 18px; gap: 24px; }\n  .welcome h1, .complete h1 { font-size: 54px; }\n  .welcome-lede { font-size: 14px; }\n  .lesson-preview { grid-template-columns: 1fr; }\n  .lesson-preview > div { display: grid; grid-template-columns: 28px 1fr; }\n  .lesson-preview span { grid-row: 1 / 3; }\n  .lesson-preview b { margin-top: 0; }\n  .welcome-start { width: 100%; }\n  .coach-preview-frame { min-height: 340px; }\n  .coach-preview-copy { left: 22px; right: 22px; bottom: 24px; }\n  .coach-preview-copy h2 { font-size: 34px; }\n  .lesson { padding-top: 16px; }\n  .stepper { top: 66px; margin-bottom: 10px; }\n  .stepper li { gap: 0; }\n  .lesson-grid { border-radius: 18px; }\n  .coach-stage { top: 126px; min-height: 34dvh; }\n  .coach-caption { left: 12px; right: 12px; bottom: 12px; padding: 11px 13px; }\n  .coach-caption p { font-size: 11px; }\n  .coach-state { top: 12px; left: 12px; }\n  .preview-ribbon { top: 12px; right: 12px; max-width: 46%; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }\n  .task-panel { min-height: 500px; padding: 27px 20px 23px; }\n  .task-heading h2 { font-size: 32px; }\n  .phrase-card { margin-top: 25px; padding: 21px; }\n  .target-phrase { font-size: 29px; }\n  .task-actions { flex-direction: column-reverse; }\n  .task-actions .primary-button, .task-actions .secondary-button { width: 100%; }\n  .learned-list { grid-template-columns: 1fr; }\n  .complete-actions { flex-direction: column; }\n  .complete-actions .primary-button, .complete-actions .secondary-button { width: 100%; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }\n}\n";
const JS = "(() => {\n  \"use strict\";\n\n  const LESSON = [\n    {\n      target: \"Tavus is more than a digital face.\",\n      translation: \"Tavus 不只是一个数字人脸。\",\n      chunks: [\"Tavus is more than\", \"a digital face\"],\n      fixChunk: \"more than a digital face\",\n      fixTitle: \"把这一段连成一个意群\",\n      fixCopy: \"不要在 more 和 than 中间停顿。先听教练说这一小段，再一口气跟上。\",\n      recallCue: \"请用英文表达：Tavus 不只是一个数字人脸。\",\n      useQuestion: \"If Tavus is more than a digital face, what is the real product?\"\n    },\n    {\n      target: \"The face is the interface; the real product is the system behind it.\",\n      translation: \"人脸是交互界面，真正的产品是它背后的系统。\",\n      chunks: [\"The face is the interface\", \"the real product\", \"is the system behind it\"],\n      fixChunk: \"the system behind it\",\n      fixTitle: \"把重音放在 system 上\",\n      fixCopy: \"face 是表层，system 才是对比重点。让 system 比前后的词更清楚。\",\n      recallCue: \"请用英文表达：人脸是界面，真正的产品是背后的系统。\",\n      useQuestion: \"What do you mean by the system behind the face?\"\n    },\n    {\n      target: \"It combines perception, memory, and orchestration to make conversations feel responsive.\",\n      translation: \"它把感知、记忆和编排结合起来，让对话真正有响应感。\",\n      chunks: [\"It combines perception\", \"memory and orchestration\", \"to make conversations feel responsive\"],\n      fixChunk: \"perception, memory, and orchestration\",\n      fixTitle: \"三个能力要有清楚的节奏\",\n      fixCopy: \"把 perception、memory、orchestration 当成三个并列拍点，不要挤成一团。\",\n      recallCue: \"请用英文表达：它结合感知、记忆和编排，让对话更有响应感。\",\n      useQuestion: \"How do perception, memory, and orchestration change the user experience?\"\n    }\n  ];\n\n  const STEPS = [\"listen\", \"repeat\", \"fix\", \"recall\", \"use\"];\n  const STEP_COPY = {\n    listen: {\n      index: \"第 1 / 5 步 · LISTEN\",\n      title: \"先听教练说，不用开口。\",\n      instruction: \"看着教练，注意句子里的自然意群。\",\n      primary: \"轮到我\",\n      secondary: \"再听一遍\",\n      help: \"听清楚以后，点击“轮到我”。\"\n    },\n    repeat: {\n      index: \"第 2 / 5 步 · REPEAT\",\n      title: \"照着读一遍，不必完美。\",\n      instruction: \"保留句子的节奏，先把完整意思说出来。\",\n      primary: \"开始跟读\",\n      secondary: \"改为输入\",\n      help: \"点击后开始说；说完停顿，或点“完成”。\"\n    },\n    fix: {\n      index: \"第 3 / 5 步 · FIX ONE THING\",\n      title: \"只练这一小段。\",\n      instruction: \"一次只改一个动作，比看一排分数更有用。\",\n      primary: \"练这一小段\",\n      secondary: \"听这一小段\",\n      help: \"听一次，再照着教练的节奏说。\"\n    },\n    recall: {\n      index: \"第 4 / 5 步 · RECALL\",\n      title: \"现在不看英文，说出同样意思。\",\n      instruction: \"不必逐字一样；重点是从记忆里把表达找回来。\",\n      primary: \"开始脱稿说\",\n      secondary: \"给我一个提示\",\n      help: \"英文会被藏起来，只保留中文意思。\"\n    },\n    use: {\n      index: \"第 5 / 5 步 · USE\",\n      title: \"把刚学的表达用进回答。\",\n      instruction: \"教练会问一个真实问题。用自己的内容回答，不要背句子。\",\n      primary: \"回答教练\",\n      secondary: \"再听问题\",\n      help: \"尽量用到刚学的表达；答案可以自由发挥。\"\n    }\n  };\n\n  const $ = id => document.getElementById(id);\n  const setText = (id, value) => { const node = $(id); if (node) node.textContent = value ?? \"\"; };\n\n  const state = {\n    sentenceIndex: 0,\n    step: \"listen\",\n    stepComplete: false,\n    configured: false,\n    baseMode: \"offline\",\n    call: null,\n    conversationId: null,\n    connecting: null,\n    recognition: null,\n    transcript: \"\",\n    mediaRecorder: null,\n    mediaStream: null,\n    audioChunks: [],\n    currentAudioUrl: null,\n    silenceTimer: null,\n    recording: false,\n    records: LESSON.map(() => ({})),\n    pendingCoachText: \"\",\n    coachRestoreTimer: null,\n    failureInProgress: false\n  };\n\n  async function fetchJSON(url, options = {}) {\n    const response = await fetch(url, {\n      ...options,\n      headers: { \"content-type\": \"application/json\", ...(options.headers || {}) }\n    });\n    const payload = await response.json().catch(() => ({}));\n    if (!response.ok) throw new Error(payload.error || payload.message || `Request failed (${response.status})`);\n    return payload;\n  }\n\n  function setView(view) {\n    document.body.dataset.view = view;\n    $(\"welcome\").hidden = view !== \"welcome\";\n    $(\"lesson\").hidden = view !== \"lesson\";\n    $(\"complete\").hidden = view !== \"complete\";\n    $(\"lesson-progress\").hidden = view !== \"lesson\";\n    $(\"exit-button\").hidden = view !== \"lesson\";\n    window.scrollTo({ top: 0, behavior: \"smooth\" });\n  }\n\n  function setCoachVisual(mode, label) {\n    document.body.dataset.coachMode = mode;\n    setText(\"coach-state-label\", label);\n  }\n\n  function restoreCoachState() {\n    if (state.baseMode === \"tavus-live\") {\n      setCoachVisual(\"tavus-live\", \"Tavus 视频教练已连接\");\n    } else {\n      setCoachVisual(\"offline\", \"等待 Tavus 视频教练\");\n    }\n  }\n\n  function setWelcomeStatus(mode, title, detail) {\n    document.body.dataset.coachMode = mode;\n    setText(\"welcome-status\", title);\n    setText(\"welcome-status-detail\", detail);\n  }\n\n  async function checkCapability() {\n    try {\n      const status = await fetchJSON(\"/api/tavus/status\", { headers: {} });\n      state.configured = Boolean(status.configured);\n      if (state.configured) {\n        setWelcomeStatus(\"tavus-ready\", \"Tavus 已配置，开始时尝试连接\", \"远端教练真正加入后，页面才会显示“实时已连接”\");\n      } else if (status.has_key) {\n        setWelcomeStatus(\"unavailable\", \"Tavus 密钥验证失败\", status.error || \"请轮换服务端密钥后再连接\");\n      } else {\n        setWelcomeStatus(\"offline\", \"真实 Tavus 尚未配置\", \"配置完成前不会用静态人脸冒充视频教练\");\n      }\n    } catch {\n      state.configured = false;\n      setWelcomeStatus(\"unavailable\", \"暂时无法检查 Tavus\", \"课程仍可使用本机语音完成\");\n    }\n  }\n\n  function currentLesson() { return LESSON[state.sentenceIndex]; }\n\n  function updateStepper() {\n    const current = STEPS.indexOf(state.step);\n    document.querySelectorAll(\".stepper li\").forEach((item, index) => {\n      item.classList.toggle(\"active\", index === current);\n      item.classList.toggle(\"done\", index < current);\n      const number = item.querySelector(\":scope > span\");\n      if (number) number.textContent = index < current ? \"✓\" : String(index + 1);\n    });\n  }\n\n  function renderChunks(chunks) {\n    const root = $(\"chunks\");\n    root.replaceChildren();\n    chunks.forEach(chunk => {\n      const chip = document.createElement(\"span\");\n      chip.textContent = chunk;\n      root.appendChild(chip);\n    });\n  }\n\n  function resetCaptureUI() {\n    $(\"capture-result\").hidden = true;\n    $(\"text-entry\").hidden = true;\n    $(\"task-note\").hidden = true;\n    $(\"typed-answer\").value = \"\";\n    $(\"play-recording\").hidden = true;\n    $(\"primary-action\").hidden = false;\n    $(\"secondary-action\").hidden = false;\n    state.stepComplete = false;\n    state.transcript = \"\";\n    if (state.currentAudioUrl) {\n      URL.revokeObjectURL(state.currentAudioUrl);\n      state.currentAudioUrl = null;\n    }\n  }\n\n  function renderStep({ announce = false } = {}) {\n    const lesson = currentLesson();\n    const copy = STEP_COPY[state.step];\n    document.body.dataset.lessonStep = state.step;\n    setText(\"sentence-count\", `第 ${state.sentenceIndex + 1} / ${LESSON.length} 句`);\n    setText(\"task-index\", copy.index);\n    setText(\"task-title\", copy.title);\n    setText(\"task-instruction\", state.step === \"recall\" ? lesson.recallCue : copy.instruction);\n    const visiblePhrase = state.step === \"recall\"\n      ? \"英文已隐藏 · Say it from memory\"\n      : state.step === \"use\"\n        ? `Try to use: “${lesson.target}”`\n        : lesson.target;\n    setText(\"target-phrase\", visiblePhrase);\n    setText(\"translation\", lesson.translation);\n    renderChunks(lesson.chunks);\n    setText(\"primary-action\", copy.primary);\n    $(\"primary-action\").innerHTML = `<span>${copy.primary}</span><i aria-hidden=\"true\">→</i>`;\n    setText(\"secondary-action\", copy.secondary);\n    setText(\"action-help\", copy.help);\n    resetCaptureUI();\n    $(\"type-instead\").hidden = [\"listen\", \"repeat\"].includes(state.step);\n\n    if (state.step === \"fix\") {\n      $(\"task-note\").hidden = false;\n      setText(\"task-note-label\", \"只改这一处\");\n      setText(\"task-note-title\", lesson.fixTitle);\n      setText(\"task-note-copy\", lesson.fixCopy);\n    }\n    if (state.step === \"use\") {\n      setText(\"task-instruction\", `教练问：${lesson.useQuestion}`);\n    }\n    updateStepper();\n\n    if (announce) {\n      if (state.step === \"listen\") speakCoach(lesson.target);\n      if (state.step === \"fix\") speakCoach(lesson.fixChunk);\n      if (state.step === \"use\") speakCoach(lesson.useQuestion);\n    }\n  }\n\n  function updateAfterCapture(text) {\n    state.stepComplete = true;\n    $(\"capture-result\").hidden = false;\n    setText(\"capture-label\", state.step === \"use\" ? \"你的回答\" : \"我听到你说\");\n    setText(\"capture-text\", text);\n    $(\"text-entry\").hidden = true;\n    $(\"type-instead\").hidden = true;\n    $(\"primary-action\").hidden = false;\n    $(\"secondary-action\").hidden = false;\n    $(\"play-recording\").hidden = !state.currentAudioUrl;\n\n    const nextLabels = {\n      repeat: \"看这一处怎么改\",\n      fix: \"现在脱稿说\",\n      recall: \"放进对话里\",\n      use: state.sentenceIndex < LESSON.length - 1 ? \"下一句\" : \"完成课程\"\n    };\n    const label = nextLabels[state.step] || \"继续\";\n    $(\"primary-action\").innerHTML = `<span>${label}</span><i aria-hidden=\"true\">→</i>`;\n    setText(\"action-help\", state.step === \"use\" ? \"完成了：你已经把这句话放进真实回答。\" : \"听到了。继续下一步，把刚才的表达留下来。\");\n\n    if (state.step === \"repeat\") {\n      const missing = findMissingChunk(text, currentLesson().chunks);\n      $(\"task-note\").hidden = false;\n      setText(\"task-note-label\", missing ? \"下一步会补上这一段\" : \"下一步只调一个细节\");\n      setText(\"task-note-title\", missing ? `再练：${missing}` : currentLesson().fixTitle);\n      setText(\"task-note-copy\", missing ? \"转写里没有完整识别到这个意群。先不打分，下一步把它单独说清楚。\" : currentLesson().fixCopy);\n    }\n  }\n\n  function normalizedWords(text) {\n    return String(text || \"\").toLowerCase().replace(/[^a-z0-9'\\s]/g, \" \").split(/\\s+/).filter(Boolean);\n  }\n\n  function findMissingChunk(text, chunks) {\n    const heard = new Set(normalizedWords(text));\n    return chunks.find(chunk => normalizedWords(chunk).some(word => !heard.has(word))) || \"\";\n  }\n\n  function finishCapturedText(rawText) {\n    const text = String(rawText || \"\").trim().replace(/\\s+/g, \" \");\n    if (!text) {\n      showTextEntry(\"没有听清这一遍。你可以再说一次，或输入你刚才说的句子。\");\n      return;\n    }\n    state.records[state.sentenceIndex][state.step] = {\n      text,\n      at: Date.now(),\n      audioUrl: state.currentAudioUrl || \"\"\n    };\n    updateAfterCapture(text);\n  }\n\n  function showTextEntry(message = \"不方便开麦也没关系。输入你想说的英文，继续同一套练习。\") {\n    $(\"text-entry\").hidden = false;\n    $(\"capture-result\").hidden = true;\n    $(\"type-instead\").hidden = true;\n    $(\"primary-action\").hidden = true;\n    $(\"secondary-action\").hidden = true;\n    setText(\"action-help\", message);\n    setTimeout(() => $(\"typed-answer\").focus(), 0);\n  }\n\n  function getRecognition() {\n    const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;\n    if (!Recognition) return null;\n    const recognition = new Recognition();\n    recognition.lang = \"en-US\";\n    recognition.continuous = true;\n    recognition.interimResults = true;\n    recognition.maxAlternatives = 1;\n    return recognition;\n  }\n\n  async function beginCapture() {\n    if (state.recording) return;\n    state.stepComplete = false;\n    state.transcript = \"\";\n    state.audioChunks = [];\n    $(\"capture-result\").hidden = true;\n    $(\"text-entry\").hidden = true;\n\n    let stream = null;\n    try {\n      stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });\n    } catch {\n      showTextEntry(\"无法使用麦克风。请允许麦克风权限，或直接输入你想说的英文。\");\n      return;\n    }\n\n    state.mediaStream = stream;\n    state.recording = true;\n    $(\"recording-toast\").hidden = false;\n    setText(\"recording-hint\", state.step === \"use\" ? \"回答完整后点“完成”\" : \"说完后停顿，或点“完成”\");\n    setCoachVisual(\"listening\", \"轮到你 · 正在听\");\n    setText(\"caption-speaker\", \"你\");\n    setText(\"caption-text\", \"开始说吧，我会把听到的词显示出来。\");\n\n    if (window.MediaRecorder) {\n      try {\n        const recorder = new MediaRecorder(stream);\n        state.mediaRecorder = recorder;\n        recorder.ondataavailable = event => { if (event.data?.size) state.audioChunks.push(event.data); };\n        recorder.onstop = () => {\n          if (!state.audioChunks.length) return;\n          const blob = new Blob(state.audioChunks, { type: recorder.mimeType || \"audio/webm\" });\n          if (state.currentAudioUrl) URL.revokeObjectURL(state.currentAudioUrl);\n          state.currentAudioUrl = URL.createObjectURL(blob);\n          $(\"play-recording\").hidden = $(\"capture-result\").hidden;\n          const record = state.records[state.sentenceIndex]?.[state.step];\n          if (record) record.audioUrl = state.currentAudioUrl;\n        };\n        recorder.start();\n      } catch {\n        state.mediaRecorder = null;\n      }\n    }\n\n    const recognition = getRecognition();\n    state.recognition = recognition;\n    if (!recognition) {\n      setText(\"recording-hint\", \"录音中；完成后请确认文字\");\n      return;\n    }\n\n    let finalText = \"\";\n    recognition.onresult = event => {\n      let interim = \"\";\n      for (let i = event.resultIndex; i < event.results.length; i += 1) {\n        const chunk = event.results[i][0]?.transcript || \"\";\n        if (event.results[i].isFinal) finalText += `${chunk} `;\n        else interim += chunk;\n      }\n      state.transcript = `${finalText}${interim}`.trim();\n      setText(\"caption-text\", state.transcript || \"正在听…\");\n      clearTimeout(state.silenceTimer);\n      if (finalText.trim()) state.silenceTimer = setTimeout(() => stopCapture(), 1500);\n    };\n    recognition.onerror = event => {\n      if (event.error === \"not-allowed\" || event.error === \"service-not-allowed\") {\n        stopCapture({ showFallback: true });\n      }\n    };\n    recognition.onend = () => {\n      if (state.recording && state.transcript) stopCapture();\n    };\n    try { recognition.start(); }\n    catch { setText(\"recording-hint\", \"录音中；完成后请确认文字\"); }\n  }\n\n  function stopCapture({ showFallback = false } = {}) {\n    if (!state.recording) {\n      if (showFallback) showTextEntry();\n      return;\n    }\n    state.recording = false;\n    clearTimeout(state.silenceTimer);\n    state.silenceTimer = null;\n    $(\"recording-toast\").hidden = true;\n    try { state.recognition?.stop(); } catch {}\n    state.recognition = null;\n    try {\n      if (state.mediaRecorder?.state !== \"inactive\") state.mediaRecorder?.stop();\n    } catch {}\n    state.mediaRecorder = null;\n    state.mediaStream?.getTracks().forEach(track => track.stop());\n    state.mediaStream = null;\n    restoreCoachState();\n    if (showFallback || !state.transcript.trim()) showTextEntry();\n    else finishCapturedText(state.transcript);\n  }\n\n  async function speakCoach(text) {\n    const phrase = String(text || \"\").trim();\n    if (!phrase) return;\n    state.pendingCoachText = phrase;\n    setText(\"caption-speaker\", \"教练\");\n    setText(\"caption-text\", phrase);\n    setCoachVisual(\"speaking\", \"教练正在说\");\n\n    if (state.baseMode === \"tavus-live\" && state.call && state.conversationId) {\n      try {\n        await state.call.sendAppMessage({\n          message_type: \"conversation\",\n          event_type: \"conversation.echo\",\n          conversation_id: state.conversationId,\n          properties: { modality: \"text\", text: phrase, done: true }\n        }, \"*\");\n        clearTimeout(state.coachRestoreTimer);\n        state.coachRestoreTimer = setTimeout(restoreCoachState, Math.max(5000, phrase.split(/\\s+/).length * 520 + 2500));\n        return;\n      } catch {\n        state.baseMode = \"audio\";\n      }\n    }\n\n    showConnectionFailure(\"需要先连接真实 Tavus 视频，教练才会示范这句话。\");\n  }\n\n  function normalizeRole(role) {\n    const value = String(role || \"\").toLowerCase();\n    if ([\"pal\", \"replica\", \"assistant\", \"agent\"].includes(value)) return \"coach\";\n    if ([\"user\", \"participant\", \"human\"].includes(value)) return \"user\";\n    return value;\n  }\n\n  function handleTavusMessage(event) {\n    const message = event?.data || event;\n    if (!message || typeof message !== \"object\") return;\n    if (message.conversation_id && message.conversation_id !== state.conversationId) return;\n    const role = normalizeRole(message.properties?.role);\n    const speech = message.properties?.speech || message.properties?.text || message.properties?.transcript || \"\";\n\n    if (message.event_type === \"conversation.started_speaking\") {\n      if (role === \"coach\") setCoachVisual(\"speaking\", \"教练正在说\");\n      return;\n    }\n    if (message.event_type === \"conversation.stopped_speaking\") {\n      clearTimeout(state.coachRestoreTimer);\n      restoreCoachState();\n      return;\n    }\n    if (message.event_type !== \"conversation.utterance\" || !speech) return;\n\n    if (role === \"coach\") {\n      setText(\"caption-speaker\", \"教练\");\n      setText(\"caption-text\", speech);\n      return;\n    }\n    if (role === \"user\") {\n      setText(\"caption-speaker\", \"你\");\n      setText(\"caption-text\", speech);\n      if (state.recording) {\n        state.transcript = speech;\n        clearTimeout(state.silenceTimer);\n        state.silenceTimer = setTimeout(() => stopCapture(), 350);\n      }\n    }\n  }\n\n  async function connectTavus() {\n    if (state.baseMode === \"tavus-live\" && state.call) return true;\n    if (state.connecting) return state.connecting;\n    state.connecting = (async () => {\n      $(\"connection-card\").hidden = true;\n      setCoachVisual(\"connecting\", \"正在请视频教练加入\");\n      setText(\"preview-ribbon\", \"CONNECTING TO TAVUS…\");\n      try {\n        if (!window.Daily) throw new Error(\"Daily video client did not load.\");\n        const room = await fetchJSON(\"/api/tavus/conversations\", {\n          method: \"POST\",\n          body: JSON.stringify({ topic: \"Tavus interview English\", focus: \"language_lesson\" })\n        });\n        state.conversationId = room.conversation_id;\n        const call = window.Daily.createFrame($(\"daily-stage\"), {\n          showLeaveButton: false,\n          showFullscreenButton: false,\n          showLocalVideo: true,\n          iframeStyle: { width: \"100%\", height: \"100%\", border: \"0\" }\n        });\n        state.call = call;\n        call.on(\"app-message\", handleTavusMessage);\n        call.on(\"error\", () => { void failConnection(\"视频连接发生错误。学习进度已经保留。\"); });\n        call.on(\"left-meeting\", () => {\n          if (document.body.dataset.view === \"lesson\") void failConnection(\"视频连接已经结束。学习进度还在，你可以重连或继续语音练习。\");\n        });\n\n        const remoteJoined = new Promise((resolve, reject) => {\n          const timer = setTimeout(() => reject(new Error(\"The coach did not join in time.\")), 20000);\n          const accept = participant => {\n            const videoReady = participant?.video || participant?.tracks?.video?.state === \"playable\";\n            if (participant && !participant.local && videoReady) {\n              clearTimeout(timer);\n              resolve(true);\n            }\n          };\n          call.on(\"participant-joined\", event => accept(event?.participant));\n          call.on(\"participant-updated\", event => accept(event?.participant));\n        });\n\n        $(\"daily-stage\").hidden = false;\n        $(\"daily-stage\").classList.add(\"pending\");\n        await call.join({\n          url: room.conversation_url,\n          token: room.meeting_token,\n          startVideoOff: true,\n          startAudioOff: true\n        });\n        await remoteJoined;\n\n        state.baseMode = \"tavus-live\";\n        $(\"daily-stage\").classList.remove(\"pending\");\n        $(\"coach-still\").hidden = true;\n        $(\"preview-ribbon\").hidden = true;\n        setCoachVisual(\"tavus-live\", \"Tavus 视频教练已连接\");\n        return true;\n      } catch (error) {\n        await failConnection(error.message || \"视频教练暂时没有加入。\");\n        return false;\n      } finally {\n        state.connecting = null;\n      }\n    })();\n    return state.connecting;\n  }\n\n  function showConnectionFailure(detail) {\n    state.baseMode = \"offline\";\n    $(\"daily-stage\").hidden = true;\n    $(\"coach-still\").hidden = false;\n    $(\"preview-ribbon\").hidden = false;\n    setText(\"preview-ribbon\", \"等待真实 TAVUS 视频\");\n    setCoachVisual(\"unavailable\", \"视频教练暂未连接\");\n    $(\"connection-card\").hidden = false;\n    setText(\"connection-copy\", detail || \"这不是预览模式。请重新连接真实 Tavus 视频教练。\");\n  }\n\n  async function failConnection(detail) {\n    if (state.failureInProgress) return;\n    state.failureInProgress = true;\n    try {\n      await destroyCall(true);\n      state.baseMode = \"offline\";\n      showConnectionFailure(detail);\n    } finally {\n      state.failureInProgress = false;\n    }\n  }\n\n  async function destroyCall(endRemote = true) {\n    const call = state.call;\n    const conversationId = state.conversationId;\n    state.call = null;\n    state.conversationId = null;\n    if (call) {\n      try { await call.leave(); } catch {}\n      try { await call.destroy(); } catch {}\n    }\n    if (endRemote && conversationId) {\n      try {\n        await fetchJSON(`/api/tavus/conversations/${encodeURIComponent(conversationId)}/end`, { method: \"POST\", body: \"{}\" });\n      } catch {}\n    }\n  }\n\n  async function startLesson() {\n    state.sentenceIndex = 0;\n    state.step = \"listen\";\n    state.records = LESSON.map(() => ({}));\n    setView(\"lesson\");\n    renderStep();\n    if (state.configured) {\n      await connectTavus();\n    } else {\n      showConnectionFailure(\"这个部署还没有可用的 Tavus 服务端密钥，无法创建真实视频房间。\");\n    }\n  }\n\n  function advanceAfterCapture() {\n    if (state.step === \"repeat\") state.step = \"fix\";\n    else if (state.step === \"fix\") state.step = \"recall\";\n    else if (state.step === \"recall\") state.step = \"use\";\n    else if (state.step === \"use\") {\n      if (state.sentenceIndex >= LESSON.length - 1) {\n        completeLesson();\n        return;\n      }\n      state.sentenceIndex += 1;\n      state.step = \"listen\";\n    }\n    renderStep({ announce: state.step === \"fix\" || state.step === \"use\" || state.step === \"listen\" });\n  }\n\n  function handlePrimary() {\n    if (state.step === \"listen\") {\n      state.step = \"repeat\";\n      renderStep();\n      return;\n    }\n    if (state.stepComplete) {\n      advanceAfterCapture();\n      return;\n    }\n    beginCapture();\n  }\n\n  function handleSecondary() {\n    const lesson = currentLesson();\n    if (state.step === \"listen\") speakCoach(lesson.target);\n    else if (state.step === \"repeat\") showTextEntry();\n    else if (state.step === \"fix\") speakCoach(lesson.fixChunk);\n    else if (state.step === \"recall\") {\n      $(\"task-note\").hidden = false;\n      setText(\"task-note-label\", \"一个小提示\");\n      setText(\"task-note-title\", lesson.chunks[0]);\n      setText(\"task-note-copy\", \"只看开头，剩下的自己从记忆里找回来。\");\n    } else if (state.step === \"use\") speakCoach(lesson.useQuestion);\n  }\n\n  async function completeLesson() {\n    stopCapture();\n    const completedAt = new Date().toISOString();\n    const review = {\n      completedAt,\n      dueAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),\n      phrases: LESSON.map((lesson, index) => ({\n        target: lesson.target,\n        translation: lesson.translation,\n        recall: state.records[index].recall?.text || \"\",\n        use: state.records[index].use?.text || \"\"\n      }))\n    };\n    try { localStorage.setItem(\"fluent-me:latest-lesson\", JSON.stringify(review)); } catch {}\n\n    const root = $(\"learned-list\");\n    root.replaceChildren();\n    review.phrases.forEach((phrase, index) => {\n      const card = document.createElement(\"article\");\n      card.className = \"learned-item\";\n      const number = document.createElement(\"span\");\n      number.textContent = `0${index + 1} · LEARNED`;\n      const target = document.createElement(\"p\");\n      target.textContent = phrase.target;\n      const detail = document.createElement(\"small\");\n      detail.textContent = phrase.use ? `你在对话里说：${phrase.use}` : phrase.translation;\n      card.append(number, target, detail);\n      root.appendChild(card);\n    });\n    setView(\"complete\");\n    window.speechSynthesis?.cancel();\n    await destroyCall(true);\n  }\n\n  async function exitLesson() {\n    stopCapture();\n    window.speechSynthesis?.cancel();\n    await destroyCall(true);\n    state.baseMode = \"offline\";\n    $(\"daily-stage\").hidden = true;\n    $(\"coach-still\").hidden = false;\n    $(\"preview-ribbon\").hidden = false;\n    $(\"connection-card\").hidden = true;\n    setView(\"welcome\");\n    checkCapability();\n  }\n\n  $(\"start-lesson\").addEventListener(\"click\", startLesson);\n  $(\"primary-action\").addEventListener(\"click\", handlePrimary);\n  $(\"secondary-action\").addEventListener(\"click\", handleSecondary);\n  $(\"type-instead\").addEventListener(\"click\", () => showTextEntry(\"直接输入你想说的英文，也可以走完整个练习。\"));\n  $(\"stop-recording\").addEventListener(\"click\", () => stopCapture());\n  $(\"submit-text\").addEventListener(\"click\", () => finishCapturedText($(\"typed-answer\").value));\n  $(\"edit-transcript\").addEventListener(\"click\", () => {\n    $(\"typed-answer\").value = $(\"capture-text\").textContent || \"\";\n    showTextEntry(\"修改后点击“使用这句话”。\");\n  });\n  $(\"play-recording\").addEventListener(\"click\", () => {\n    if (!state.currentAudioUrl) return;\n    window.speechSynthesis?.cancel();\n    new Audio(state.currentAudioUrl).play().catch(() => {});\n  });\n  $(\"retry-tavus\").addEventListener(\"click\", async () => {\n    $(\"connection-card\").hidden = true;\n    const connected = await connectTavus();\n    if (connected) {\n      const lesson = currentLesson();\n      if (state.step === \"fix\") speakCoach(lesson.fixChunk);\n      else if (state.step === \"use\") speakCoach(lesson.useQuestion);\n    }\n  });\n  $(\"exit-button\").addEventListener(\"click\", exitLesson);\n  $(\"practice-again\").addEventListener(\"click\", startLesson);\n  $(\"back-home\").addEventListener(\"click\", () => { setView(\"welcome\"); checkCapability(); });\n\n  window.addEventListener(\"beforeunload\", () => {\n    state.mediaStream?.getTracks().forEach(track => track.stop());\n    if (state.conversationId) {\n      fetch(`/api/tavus/conversations/${encodeURIComponent(state.conversationId)}/end`, {\n        method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: \"{}\", keepalive: true\n      }).catch(() => {});\n    }\n  });\n\n  if (window.speechSynthesis) window.speechSynthesis.getVoices();\n  checkCapability();\n})();\n";
const OG_BASE64 = "";
const TAVUS_BASE = "https://tavusapi.com/v2";
const DEFAULT_FACE_ID = "r90bbd427f71";
const PAL_NAME = "Fluent Me Language Coach v3";

const PAL_PROMPT = "You are the visible English coach inside Fluent Me, a five-step speaking lesson.\n\nThe Fluent Me interface owns the lesson sequence: Listen, Repeat, Fix, Recall, and Use. Never advance the lesson yourself and never give numeric scores. The app may send exact model sentences through conversation.echo. Speak those sentences exactly and naturally.\n\nWhen the learner repeats or recalls a sentence, acknowledge its meaning in at most one short sentence, then wait. Do not interrupt. During the Use step, ask or answer one natural follow-up so the new expression enters a real conversation. Keep every turn short, warm, spoken-first, and appropriate for an intermediate English learner.\n\nRaven observations are uncertain context only. Never infer ability, personality, protected traits, or mental state from perception. You are an AI English coach, not a human and not an examiner.";

const LESSON_CONTEXT = "Today's three target phrases are:\n1. Tavus is more than a digital face.\n2. The face is the interface; the real product is the system behind it.\n3. It combines perception, memory, and orchestration to make conversations feel responsive.\n\nThe learner is preparing to explain Tavus in an interview. The app controls exact demonstrations and the learner's current step. Keep spontaneous replies brief so they do not compete with the lesson UI.";

const SECURITY_HEADERS = {
  "x-content-type-options": "nosniff",
  "referrer-policy": "no-referrer",
  "permissions-policy": "camera=(), microphone=(self), geolocation=()",
};

const json = (value, status = 200) => new Response(JSON.stringify(value), {
  status,
  headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
});

const imageResponse = (base64, type = "image/png") => {
  const raw = atob(base64);
  const bytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i);
  return new Response(bytes, { headers: { "content-type": type, "cache-control": "public, max-age=86400" } });
};

async function tavusRequest(env, path, options = {}) {
  const key = String(env.TAVUS_API_KEY || "").trim();
  if (!key) throw Object.assign(new Error("Tavus live video is not configured on this deployment."), { status: 503 });
  const response = await fetch(TAVUS_BASE + path, {
    method: options.method || "GET",
    headers: {
      "accept": "application/json",
      "content-type": "application/json",
      "x-api-key": key,
    },
    body: options.body == null ? undefined : JSON.stringify(options.body),
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    const message = payload.message || payload.error || "Tavus request failed.";
    throw Object.assign(new Error(String(message).slice(0, 240)), { status: response.status });
  }
  return payload;
}

async function ensurePal(env) {
  const configured = String(env.TAVUS_PAL_ID || "").trim();
  if (configured) return configured;

  const listed = await tavusRequest(env, "/pals?limit=100");
  const pals = listed.data || listed.pals || [];
  const existing = pals.find(pal => pal.pal_name === PAL_NAME && pal.pal_id);
  if (existing) return existing.pal_id;

  const faceId = String(env.TAVUS_FACE_ID || DEFAULT_FACE_ID).trim();
  const created = await tavusRequest(env, "/pals", {
    method: "POST",
    body: {
      pal_name: PAL_NAME,
      pipeline_mode: "full",
      system_prompt: PAL_PROMPT,
      default_face_id: faceId,
      disclosure_type: "always",
      verbal_disclosure: "Just so you know, you're speaking with an AI English coach.",
      visual_disclosure: "You are speaking with an AI English coach.",
      layers: {
        perception: {
          perception_model: "raven-1",
          emotion_recognition: "limited",
          visual_awareness_queries: ["What visible object or screen content is directly relevant to this language practice?"],
          audio_awareness_queries: ["Is background noise making the learner difficult to hear? Describe only observable audio conditions."],
        },
        conversational_flow: {
          turn_detection_model: "sparrow-1",
          turn_taking_patience: "high",
          pal_interruptibility: "high",
        },
      },
    },
  });
  if (!created.pal_id) throw Object.assign(new Error("Tavus created no usable PAL."), { status: 502 });
  return created.pal_id;
}

async function createConversation(request, env) {
  if (!String(env.TAVUS_API_KEY || "").trim()) {
    return json({ error: "Tavus live video is not configured on this deployment.", reason: "not_configured" }, 503);
  }
  try {
    const palId = await ensurePal(env);
    const result = await tavusRequest(env, "/conversations", {
      method: "POST",
      body: {
        pal_id: palId,
        conversation_name: "Fluent Me · Tavus interview English",
        conversational_context: LESSON_CONTEXT,
        custom_greeting: "Tavus is more than a digital face.",
        require_auth: true,
        max_participants: 2,
        audio_only: false,
        properties: {
          participant_absent_timeout: 60,
          participant_left_timeout: 15,
          max_call_duration: 900,
        },
      },
    });
    const required = ["conversation_id", "conversation_url", "meeting_token"];
    if (required.some(key => !result[key])) throw Object.assign(new Error("Tavus returned an incomplete private room."), { status: 502 });
    return json({
      conversation_id: result.conversation_id,
      conversation_url: result.conversation_url,
      meeting_token: result.meeting_token,
      status: result.status || "active",
    });
  } catch (error) {
    const status = Number(error.status) || 502;
    const safeStatus = status >= 400 && status < 600 ? status : 502;
    const message = safeStatus === 401 || safeStatus === 403
      ? "Tavus rejected the server credential. Rotate it and reconnect."
      : error.message || "Could not create the Tavus room.";
    return json({ error: message, reason: "tavus" }, safeStatus);
  }
}

async function endConversation(conversationId, env) {
  if (!String(env.TAVUS_API_KEY || "").trim()) return json({ status: "not_configured" });
  try {
    await tavusRequest(env, "/conversations/" + encodeURIComponent(conversationId) + "/end", { method: "POST" });
    return json({ status: "ended" });
  } catch (error) {
    return json({ error: error.message || "Could not end the Tavus room." }, Number(error.status) || 502);
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/" || url.pathname === "/index.html") {
      return new Response(HTML, { headers: { ...SECURITY_HEADERS, "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
    }
    if (url.pathname === "/static/live.css") {
      return new Response(CSS, { headers: { "content-type": "text/css; charset=utf-8", "cache-control": "public, max-age=3600" } });
    }
    if (url.pathname === "/static/live.js") {
      return new Response(JS, { headers: { "content-type": "text/javascript; charset=utf-8", "cache-control": "public, max-age=3600" } });
    }
    if (url.pathname === "/static/og-language-lesson.png") return imageResponse(OG_BASE64);
    if (url.pathname === "/api/tavus/status") {
      const hasKey = Boolean(String(env.TAVUS_API_KEY || "").trim());
      if (!hasKey) return json({ configured: false, has_key: false, reason: "not_configured" });
      try {
        await tavusRequest(env, "/pals?limit=1");
        return json({
          configured: true,
          has_key: true,
          validated: true,
          mode: "tavus_live",
          experience_mode: "tavus_live",
          pal_ready: Boolean(String(env.TAVUS_PAL_ID || "").trim()),
          capabilities: { face: "Phoenix", perception: "Raven-1", turn_taking: "Sparrow-1" },
        });
      } catch (error) {
        return json({
          configured: false,
          has_key: true,
          validated: false,
          reason: "credential_rejected",
          error: error.status === 401 || error.status === 403 ? "Tavus rejected the server credential." : "Tavus could not be reached.",
        });
      }
    }
    if (url.pathname === "/api/tavus/conversations" && request.method === "POST") {
      return createConversation(request, env);
    }
    const endMatch = url.pathname.match(/^\/api\/tavus\/conversations\/([^/]+)\/end$/);
    if (endMatch && request.method === "POST") return endConversation(decodeURIComponent(endMatch[1]), env);
    return new Response("Not found", { status: 404 });
  },
};
